import { NextResponse } from 'next/server';

// Special route handler for sign-in page
export function GET(request) {
  console.log('Sign-in root route handler activated');

  // Get the URL from the request
  const url = new URL(request.url);

  // Get the redirect_url parameter
  const redirectUrl = url.searchParams.get('redirect_url');

  // If there's a redirect_url parameter that includes http, redirect to dashboard
  if (redirectUrl && redirectUrl.includes('http')) {
    console.log('Detected http in redirect_url, redirecting to dashboard');
    const dashboardUrl = new URL('/dashboard', process.env.NEXT_PUBLIC_URL || 'http://localhost:3001');
    return NextResponse.redirect(dashboardUrl, { status: 307 });
  }

  // If there's a redirect_url parameter that starts with /, use it
  if (redirectUrl && redirectUrl.startsWith('/')) {
    console.log('Redirecting to', redirectUrl);
    const targetUrl = new URL(redirectUrl, process.env.NEXT_PUBLIC_URL || 'http://localhost:3001');
    return NextResponse.redirect(targetUrl, { status: 307 });
  }

  // If we're on the sign-in page without a redirect URL, let the page handle it
  // We must return a Response object, so we'll return a NextResponse.next()
  console.log('No redirect URL, letting the page handle it');
  return NextResponse.next();
}
